baseline_files.transport.py:
def offer_attempt(state, account, observed_revision):
    if state['revision'] != observed_revision:
        raise RuntimeError('control contention')
    state['revision'] += 1
    state['eligibility'].add(account)

def reserve_stock(state, account):
    if state['stock'] <= 0:
        raise ValueError('sold out')
    state['stock'] -= 1
    state['owners'].append(account)

